function authShell(title,sub,form){return `<div class="auth-wrap"><aside class="auth-aside">${brand()}<div class="auth-message"><div class="eyebrow" style="color:#b9ef79">DATA OPERATIONS, WITH CLARITY</div><h1>Make every change a considered one.</h1><p>Validate your customer data, understand every proposed change, and give your team a dependable record before syncing.</p></div><div class="auth-quote">“A clear preview is the first step to a confident sync.”</div></aside><main class="auth-main"><form class="auth-form" id="auth-form"><div class="eyebrow">SYNCShield WORKSPACE</div><h2>${title}</h2><p>${sub}</p>${form}<a class="auth-back" href="/" data-nav="/">← Back to SyncShield</a></form></main></div>`}
function signup(){app.innerHTML=authShell('Create your account','Start with a free workspace. No credit card required.',`<div id="error"></div><div class="field"><label>Full name</label><input name="name" autocomplete="name" placeholder="e.g. Ananya Rao" required maxlength="100"></div><div class="field"><label>Work email</label><input name="email" type="email" autocomplete="email" placeholder="you@company.com" required></div><div class="field-row"><div class="field"><label>Password</label><div class="password-wrap"><input name="password" type="password" autocomplete="new-password" minlength="10" placeholder="At least 10 characters" required><button type="button" class="show-pass">Show</button></div></div><div class="field"><label>Confirm password</label><input name="confirm" type="password" autocomplete="new-password" minlength="10" placeholder="Repeat password" required></div></div><div class="field"><label>Company or workspace</label><input name="company" placeholder="Your company name" maxlength="100" required></div><label class="checkline"><input type="checkbox" name="terms" required><span>I agree to the <a href="#" style="text-decoration:underline">Terms of Service</a> and <a href="#" style="text-decoration:underline">Privacy Policy</a>.</span></label><button class="btn btn-dark auth-submit" type="submit">Create account <span>→</span></button><div class="auth-foot">Already have an account? <a href="/login" data-nav="/login">Sign in</a></div>`);wireAuth('signup');}
function login(){app.innerHTML=authShell('Welcome back','Sign in to your SyncShield workspace.',`<div id="error"></div><div class="field"><label>Work email</label><input name="email" type="email" autocomplete="email" placeholder="you@company.com" required></div><div class="field"><div style="display:flex;justify-content:space-between"><label>Password</label><a href="#" style="font-size:11px;color:#63834e">Forgot password?</a></div><div class="password-wrap"><input name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" class="show-pass">Show</button></div></div><button class="btn btn-dark auth-submit" type="submit">Sign in <span>→</span></button><div class="auth-foot">New to SyncShield? <a href="/signup" data-nav="/signup">Create an account</a></div>`);wireAuth('login');}
function wireAuth(kind){const form=$('#auth-form');$('.show-pass',form)?.addEventListener('click',e=>{const input=e.currentTarget.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';e.currentTarget.textContent=input.type==='password'?'Show':'Hide'});form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),err=$('#error');err.innerHTML='';const btn=$('button[type=submit]',form);if(kind==='signup'&&f.get('password')!==f.get('confirm')){err.innerHTML='<div class="form-error">Passwords do not match.</div>';return}btn.disabled=true;btn.textContent=kind==='signup'?'Creating workspace…':'Signing in…';try{const payload=kind==='signup'?{name:f.get('name'),email:f.get('email'),password:f.get('password'),company:f.get('company')}:{email:f.get('email'),password:f.get('password')};const d=await api('/api/'+kind,payload);nav(d.next)}catch(ex){err.innerHTML=`<div class="form-error">${esc(ex.message)}</div>`;btn.disabled=false;btn.textContent=kind==='signup'?'Create account →':'Sign in →'}})}
function onboarding(){app.innerHTML=authShell('Set up your workspace','A couple of details will make your first preview feel right.',`<div class="onboard-progress"><i class="active"></i><i class="active"></i><i></i></div><div id="error"></div><div class="field"><label>Workspace name</label><input name="workspace" value="${esc(currentUser?.workspace||'')}" required maxlength="100"></div><div class="field"><label>Preferred data format</label><select name="format"><option>CSV</option><option>JSON</option></select></div><div class="field"><label>What will you use SyncShield for?</label><select name="use"><option value="Customer data synchronisation">Customer data synchronisation</option><option value="Data quality checks">Data quality checks</option><option value="ERP migration">ERP migration</option></select></div><div class="field"><label>Choose your demo plan</label><select name="plan"><option>Basic</option><option>Pro</option></select><small class="muted">Pro enables the sync preview in this prototype.</small></div><div class="checkline"><span>✦</span><span>We'll add a sample customer batch so you can explore validation immediately.</span></div><button class="btn btn-dark auth-submit" type="submit">Finish setup <span>→</span></button><div class="auth-foot"><a href="#" id="skip-setup">Skip for now</a></div>`);const form=$('#auth-form');async function save(payload){try{await api('/api/onboarding',payload);currentUser=(await api('/api/me')).user;nav('/dashboard')}catch(ex){$('#error').innerHTML=`<div class="form-error">${esc(ex.message)}</div>`}}form.addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(form);$('#error').innerHTML='';await save({workspace:f.get('workspace'),format:f.get('format'),use:f.get('use'),plan:f.get('plan')})});$('#skip-setup').addEventListener('click',e=>{e.preventDefault();save({workspace:currentUser?.workspace||'My Workspace',format:'CSV',use:'Customer data synchronisation',plan:'Basic'})})}
const navItems=[['Overview','⌂'],['Data Quality','✓'],['Sync Preview','⇄'],['Run History','◷'],['Administration','▣'],['Usage & Plan','▥'],['Settings','⚙']];
function shell(content){return `<div class="app-shell"><aside class="sidebar" id="sidebar">${brand()}<div class="side-label">WORKSPACE</div>${navItems.map(([n,i])=>`<a href="#" class="side-link ${currentPage===n?'active':''}" data-page="${n}"><span class="ico">${i}</span>${n}</a>`).join('')}<div class="side-bottom"><div class="plan-box"><b>${esc(currentUser?.workspace||'Workspace')}</b>${esc(currentUser?.plan||'Basic')} plan<div style="margin-top:7px">Preview only · No ERP connected</div></div><div class="profile-mini"><div class="avatar">${esc((currentUser?.name||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div style="flex:1"><b>${esc(currentUser?.name||'User')}</b><small>${esc(currentUser?.role||'Operator')}</small></div><button class="side-link" id="logout" title="Sign out">↪</button></div></div></aside><div class="main-area"><header class="app-top"><div><button class="mobile-menu" id="menu">☰</button><span class="crumb">Workspace&nbsp; / &nbsp;${esc(currentPage)}</span></div><div class="top-user"><span class="badge-plan">${esc(currentUser?.plan||'Basic')} PLAN</span><div class="avatar">${esc((currentUser?.name||'U')[0].toUpperCase())}</div></div></header><main class="content">${content}</main></div></div>`}
function overview(){return `<div class="page-title"><div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc((currentUser?.name||'there').split(' ')[0])}</h1><p>Here's what's happening in your workspace today.</p></div><button class="btn btn-dark" data-page="Data Quality">＋ New validation</button></div><div class="grid-kpi"><div class="card kpi"><div class="kpi-top">Runs today <span class="kpi-icon">◷</span></div><div class="kpi-value" id="kpi-runs">—</div><div class="kpi-note">Saved workspace previews</div></div><div class="card kpi"><div class="kpi-top">Rows in saved runs <span class="kpi-icon">✓</span></div><div class="kpi-value" id="kpi-rows">—</div><div class="kpi-note">Based on saved previews</div></div><div class="card kpi"><div class="kpi-top">Proposed creates <span class="kpi-icon">＋</span></div><div class="kpi-value" id="kpi-create">—</div><div class="kpi-note">Preview actions only</div></div><div class="card kpi"><div class="kpi-top">Proposed updates <span class="kpi-icon">⇄</span></div><div class="kpi-value" id="kpi-update">—</div><div class="kpi-note">Preview actions only</div></div></div><div class="dash-grid"><section class="card"><div class="card-head"><h3>Run activity</h3><span>Saved previews · last 7 days</span></div><div class="chart-area" id="activity-chart"><div style="margin:auto;color:#8793a1;font-size:12px">Loading run activity…</div></div></section><section class="card"><div class="card-head"><h3>Quick actions</h3><span>Get started</span></div><div class="action-list"><div class="action-row"><span class="action-icon">↥</span><div><b>Validate a customer batch</b><small>Check data quality before processing</small></div><button data-page="Data Quality">→</button></div><div class="action-row"><span class="action-icon">⇄</span><div><b>Preview sync changes</b><small>See proposed record actions</small></div><button data-page="Sync Preview">→</button></div><div class="action-row"><span class="action-icon">◷</span><div><b>Review past runs</b><small>Inspect saved workspace history</small></div><button data-page="Run History">→</button></div></div></section></div><section class="card section-card"><div class="card-head"><h3>Recent runs</h3><a href="#" data-page="Run History">View history →</a></div><div class="table-wrap" id="recent-runs"><div style="padding:30px;text-align:center;color:#78869a;font-size:12px">Loading workspace runs…</div></div></section>`}
function uploadPage(preview=false){return `<div class="page-title"><div><h1>${preview?'Sync Preview':'Data Quality Studio'}</h1><p>${preview?'Review proposed changes against the demo baseline. Preview only — no ERP write-back.':'Validate your customer data and understand every issue before processing.'}</p></div>${preview?`<span class="badge-plan">${currentUser?.plan==='Pro'?'PRO FEATURE':'PRO PREVIEW'}</span>`:''}</div><section class="card"><div class="card-head"><h3>${preview?'Choose a batch to preview':'Upload customer batch'}</h3><span>CSV or JSON · up to 10 rows</span></div><div style="padding:18px"><div class="upload-zone"><div style="font-size:26px">↥</div><strong>Drop your customer file here</strong><p>CSV or JSON · Maximum 10 customer records</p><button type="button" class="btn btn-outline" id="browse-files">Browse files</button><input id="file-input" type="file" accept=".csv,.json,text/csv,application/json"><span id="selected-file" class="upload-file-name" aria-live="polite">No file selected</span><button class="btn btn-light" id="sample-btn" style="margin-left:7px">Use sample data</button></div><div id="batch-area"></div><div style="display:flex;justify-content:flex-end;gap:9px;margin-top:16px"><button class="btn btn-outline" id="clear-btn">Clear</button><button class="btn btn-dark" id="run-btn">${preview?'Generate preview':'Validate batch'} →</button></div><div id="results"></div></div></section>`}
function simplePage(){let page=currentPage;let text=page==='Usage & Plan'?'Your workspace plan and recorded preview activity.':page==='Settings'?'Workspace settings and account preferences.':'Your saved validation and preview runs appear here.';return `<div class="page-title"><div><h1>${esc(page)}</h1><p>${esc(text)}</p></div></div>${page==='Usage & Plan'?`<section class="card" style="padding:24px;max-width:620px"><div class="eyebrow">WORKSPACE PLAN</div><h2 style="font:800 27px Manrope">${esc(currentUser?.plan||'Basic')}</h2><p class="muted" style="font-size:13px">${currentUser?.plan==='Pro'?'Sync preview is enabled for this prototype workspace.':'Basic includes batch validation. Choose Pro during onboarding to enable sync preview.'}</p><div class="grid-kpi" style="grid-template-columns:1fr 1fr;margin-top:20px"><div class="card kpi"><div class="kpi-top">Saved preview runs</div><div class="kpi-value" id="usage-count">—</div></div><div class="card kpi"><div class="kpi-top">Rows in saved runs</div><div class="kpi-value" id="usage-rows">—</div></div></div><p id="usage-note" class="muted" style="font-size:11px">Loading stored activity…</p><p style="font-size:11px;color:#7c8897">Usage quotas and subscription billing are not enabled in this local prototype.</p></section>`:page==='Settings'?`<section class="card" style="padding:24px;max-width:650px"><h3 style="font:700 16px Manrope">Workspace profile</h3><p class="muted" style="font-size:12px">${esc(currentUser?.workspace||'Workspace')} · ${esc(currentUser?.email||'')} · ${esc(currentUser?.role||'Operator')}</p><p class="muted" style="font-size:12px">Preferred format: ${esc(currentUser?.preferredFormat||'CSV')}</p><button class="btn btn-outline" id="settings-logout">Sign out</button></section>`:`<section class="card"><div class="card-head"><h3>Workspace run history</h3><span>Most recent first</span></div><div id="all-runs" class="table-wrap" style="padding:10px">Loading runs…</div></section>`}`}
async function renderDashboard(){let body=currentPage==='Overview'?overview():currentPage==='Data Quality'?uploadPage(false):currentPage==='Sync Preview'?uploadPage(true):simplePage();app.innerHTML=shell(body);document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();currentPage=el.dataset.page;renderDashboard()}));$('#menu')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#logout')?.addEventListener('click',logout);$('#settings-logout')?.addEventListener('click',logout);wireBatch();if(currentPage==='Overview')loadRuns('recent-runs');if(currentPage==='Run History')loadRuns('all-runs');if(currentPage==='Usage & Plan')loadRuns('usage-data')}
async function loadRuns(target){try{const {runs}=await api('/api/runs');if(target==='recent-runs'){let today=new Date().toISOString().slice(0,10),daily=runs.filter(r=>r.created_at?.slice(0,10)===today);$('#kpi-runs').textContent=daily.length;$('#kpi-rows').textContent=runs.reduce((a,r)=>a+r.input_rows,0);$('#kpi-create').textContent=runs.reduce((a,r)=>a+r.created_count,0);$('#kpi-update').textContent=runs.reduce((a,r)=>a+r.updated_count,0);$('#recent-runs').innerHTML=runTable(runs.slice(0,5));const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return d});const max=Math.max(1,...days.map(d=>runs.filter(r=>new Date(r.created_at+'Z').toDateString()===d.toDateString()).length));$('#activity-chart').innerHTML=days.map(d=>{const n=runs.filter(r=>new Date(r.created_at+'Z').toDateString()===d.toDateString()).length;return `<div class="bar-group"><i class="bar" style="height:${n?Math.max(6,n/max*86):2}%"></i><span class="bar-label">${d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2)}</span></div>`}).join('')}else if(target==='all-runs')$('#all-runs').innerHTML=runTable(runs);else if(target==='usage-data'){ $('#usage-count').textContent=runs.length;$('#usage-rows').textContent=runs.reduce((a,r)=>a+r.input_rows,0);$('#usage-note').textContent=runs.length?`Recorded for ${currentUser?.workspace||'this workspace'}.`:'No usage recorded yet. Run a Pro preview to begin.'}}catch(e){let node=document.getElementById(target);if(node)node.innerHTML=`<div style="padding:25px;color:#778398;font-size:12px">${esc(e.message)}</div>`}}
function runTable(runs){if(!runs.length)return `<div style="padding:35px;text-align:center;color:#7b8796;font-size:12px">No runs yet. Start by validating the sample customer batch.</div>`;return `<table class="data-table"><thead><tr><th>Run ID</th><th>Type</th><th>Records</th><th>Created</th><th>Updated</th><th>Status</th><th>Time</th></tr></thead><tbody>${runs.map(r=>`<tr><td><b>${esc(r.id.slice(0,10))}</b></td><td>${esc(r.kind)}</td><td>${r.input_rows}</td><td>${r.created_count}</td><td>${r.updated_count}</td><td><span class="status">${esc(r.status)}</span></td><td>${new Date(r.created_at+'Z').toLocaleString()}</td></tr>`).join('')}</tbody></table>`}
function wireBatch(){let area=$('#batch-area'),res=$('#results');if(!area)return;const showRows=()=>{area.innerHTML=`<div class="card-head" style="padding:18px 0 10px;border:0"><h3>Batch preview · ${pendingRows.length} rows</h3><span>Field order: record_id · name · version · status</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Record ID</th><th>Name</th><th>Version</th><th>Status</th></tr></thead><tbody>${pendingRows.map(r=>`<tr><td>${esc(r.record_id)}</td><td>${esc(r.name)}</td><td>${esc(r.version)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`};showRows();$('#sample-btn').onclick=()=>{pendingRows=sample.map(x=>({...x}));lastValidation=null;res.innerHTML='';showRows()};$('#clear-btn').onclick=()=>{pendingRows=[];area.innerHTML='';res.innerHTML=''};$('#file-input').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const t=await f.text();if(f.name.toLowerCase().endsWith('.json'))pendingRows=JSON.parse(t);else{const lines=t.trim().split(/\r?\n/),headers=lines.shift().split(',').map(s=>s.trim());pendingRows=lines.map(line=>{const cells=line.split(',');return Object.fromEntries(headers.map((h,i)=>[h,h==='version'?Number(cells[i]?.trim()):cells[i]?.trim()]))})}if(!Array.isArray(pendingRows))throw Error('JSON file should contain an array of customer rows.');showRows();res.innerHTML=''}catch(ex){res.innerHTML=`<div class="form-error">Could not read file: ${esc(ex.message)}</div>`}};$('#run-btn').onclick=async()=>{if(!pendingRows.length){res.innerHTML='<div class="form-error">Add rows or load the sample before continuing.</div>';return}const btn=$('#run-btn');btn.disabled=true;btn.textContent='Working…';res.innerHTML='';try{if(currentPage==='Sync Preview'){const result=await api('/api/process',{rows:pendingRows});showPreview(result)}else{const result=await api('/api/validate',{rows:pendingRows});lastValidation=result;showValidation(result)}}catch(ex){res.innerHTML=`<div class="form-error">${esc(ex.message)}${ex.data?.issues?'<ul>'+ex.data.issues.map(i=>`<li>${esc(i.rule)} · Row ${i.row}: ${esc(i.message)}</li>`).join('')+'</ul>':''}</div>`}finally{btn.disabled=false;btn.textContent=currentPage==='Sync Preview'?'Generate preview →':'Validate batch →'}}}
function showValidation(r){$('#results').innerHTML=`<div class="result-counts"><div class="count-pill"><b>${r.valid_rows}</b> Valid rows</div><div class="count-pill"><b>${r.invalid_rows}</b> Invalid rows</div><div class="count-pill">${r.issues.length?`${r.issues.length} issues found`:'No issues found'}</div></div>${r.issues.length?`<div class="table-wrap card"><table class="data-table"><thead><tr><th>Row</th><th>Record</th><th>Rule</th><th>Field</th><th>Issue</th></tr></thead><tbody>${r.issues.map(i=>`<tr class="issue"><td>${i.row}</td><td>${esc(i.record_id||'—')}</td><td>${esc(i.rule)}</td><td>${esc(i.field)}</td><td>${esc(i.message)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="card" style="padding:16px;color:#32805a;font-size:12px">✓ All rows passed validation. Your data is ready for review.</div>`}`}
function showPreview(r){$('#results').innerHTML=`<div class="result-counts"><div class="count-pill"><b>${r.input_rows}</b> Input rows</div><div class="count-pill"><b>${r.created}</b> Create</div><div class="count-pill"><b>${r.updated}</b> Update</div><div class="count-pill"><b>${r.unchanged}</b> Unchanged</div><div class="count-pill" style="margin-left:auto">Saved run <b style="font-size:12px">${esc(r.run_id)}</b></div></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Record</th><th>Action</th><th>Changes</th><th>Reason</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td><b>${esc(x.record_id)}</b></td><td><span class="tag ${x.action==='CREATE'?'tag-create':x.action==='UPDATE'?'tag-update':'tag-unchanged'}">${x.action}</span></td><td>${x.changes.length?x.changes.map(c=>`<div>${esc(c.field)}: <b>${esc(c.before)}</b> → <b>${esc(c.after)}</b></div>`).join(''):'—'}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div><div class="card" style="padding:14px;margin-top:12px;font-size:11px;color:#778398">Preview only — no ERP write-back. This result has been saved to your workspace run history.</div>`}
async function logout(){try{await api('/api/logout',{})}catch{}currentUser=null;nav('/')}
async function renderRoute(){let path=location.pathname;try{const d=await api('/api/me');currentUser=d.user}catch{currentUser=null}if(path==='/signup'){if(currentUser){nav(currentUser.onboardingComplete?'/dashboard':'/onboarding');return}signup();return}if(path==='/login'){if(currentUser){nav(currentUser.onboardingComplete?'/dashboard':'/onboarding');return}login();return}if(path==='/onboarding'){if(!currentUser){nav('/signup');return}onboarding();return}if(path==='/dashboard'||path.startsWith('/dashboard/')){if(!currentUser){nav('/login');return}if(!currentUser.onboardingComplete){nav('/onboarding');return}renderDashboard();return}if(currentUser){nav(currentUser.onboardingComplete?'/dashboard':'/onboarding');return}landing();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-nav]');if(el){e.preventDefault();nav(el.dataset.nav)}});
renderRoute();

// Operations overview and run actions use persisted, tenant-scoped API data.
function statCard(label,value,icon,sub='',tone=''){return `<div class="card kpi ${tone}"><div class="kpi-top"><span class="kpi-label">${esc(label)}</span><span class="kpi-icon">${icon}</span></div><div class="kpi-value">${esc(value)}</div>${sub?`<div class="kpi-sub">${esc(sub)}</div>`:''}</div>`}
function overview(){return `<div class="page-title overview-heading"><div><div class="eyebrow">OPERATIONS OVERVIEW</div><h1 style="margin-top:8px">Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc((currentUser?.name||'there').split(' ')[0])}</h1><p>Monitor validation activity and proposed synchronisation changes.</p><div class="overview-date">${new Date().toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'})} · ${esc(currentUser?.workspace||'Workspace')} · ${esc(currentUser?.plan||'Basic')} plan</div></div><button class="btn btn-dark" data-page="Data Quality">＋ Upload batch</button></div>
<div class="section-kicker">Run health</div><div class="grid-kpi operations" id="ops-health">${statCard('Total runs today','—','◷')}${statCard('Successful runs','—','✓')}${statCard('Failed runs','—','!','', 'kpi-danger')}${statCard('Validation errors','—','△','Invalid field issues','kpi-warn')}</div>
<div class="section-kicker">Records & quality</div><div class="grid-kpi outcomes" id="ops-outcomes">${statCard('Rows processed','—','▤')}${statCard('Created','—','＋')}${statCard('Updated','—','⇄')}${statCard('Unchanged','—','＝')}${statCard('Validation success','—','✓')}${statCard('Processing failure','—','!')}</div>
<div class="dashboard-lower"><section class="card"><div class="card-head"><h3>Daily run volume</h3><span>Last 7 days · UTC</span></div><div class="chart-area operations-chart" id="ops-chart"><div class="empty-chart">Loading workspace activity…</div></div></section><section class="card"><div class="card-head"><h3>Quick actions</h3><span>Workspace tools</span></div><div class="quick-actions"><div class="quick-action"><span class="action-icon">↥</span><div class="quick-action-copy"><b>Upload batch</b><small>Choose a CSV or JSON file</small></div><button data-page="Data Quality">Open</button></div><div class="quick-action"><span class="action-icon">✓</span><div class="quick-action-copy"><b>Validate sample</b><small>Run the two customer fixture rows</small></div><button data-action="validate-sample">Run</button></div><div class="quick-action"><span class="action-icon">◷</span><div class="quick-action-copy"><b>View history</b><small>Inspect saved workspace runs</small></div><button data-page="Run History">Open</button></div></div></section></div>
<section class="card section-card"><div class="card-head"><div><h3>Recent runs</h3><span>Only this workspace's history is shown</span></div><button class="run-action" data-page="Run History">View all history →</button></div><div class="table-wrap" id="ops-recent"><div style="padding:26px;text-align:center;color:#78869a;font-size:12px">Loading runs…</div></div></section>`}

async function renderDashboard(){
 let body=currentPage==='Overview'?overview():currentPage==='Data Quality'?uploadPage(false):currentPage==='Sync Preview'?uploadPage(true):currentPage==='Administration'?administrationPage():currentPage==='Checkout'?checkoutPage():simplePage();
 app.innerHTML=shell(body);
 document.querySelectorAll('[data-action="validate-sample"]').forEach(el=>el.addEventListener('click',async()=>{if(quickValidationBusy)return;quickValidationBusy=true;pendingRows=sample.map(r=>({...r}));pendingQuickKey=pendingQuickKey||crypto.randomUUID();pendingOperationKey=null;pendingOperationKind=null;currentPage='Data Quality';await renderDashboard();try{const r=await api('/api/validate',{rows:pendingRows},{'Idempotency-Key':pendingQuickKey});pendingQuickKey=null;cacheSubmission(r,false);showValidation(r);toast('Validation complete · run saved to history')}catch(err){$('#results').innerHTML=`<div class="form-error">${esc(err.message)}</div>`}finally{quickValidationBusy=false}}));
 $('#menu')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#logout')?.addEventListener('click',logout);$('#settings-logout')?.addEventListener('click',logout);
 wireBatch();
 if(currentPage==='Overview')loadOperations();if(currentPage==='Run History')loadRuns('all-runs');if(currentPage==='Usage & Plan')loadRuns('usage-data');if(currentPage==='Administration')loadAdministration();
 if(currentPage==='Checkout')wireCheckout();
 if(currentPage==='Sync Preview')wireBaseline();
}

async function loadOperations(){
 const chart=$('#ops-chart'),table=$('#ops-recent');
 try{
  let d;
  try{d=await api('/api/dashboard')}catch(err){
   if(err.status!==404)throw err;
   const listed=await api('/api/runs'),runs=listed.runs||[],today=new Date().toISOString().slice(0,10),rows=runs.reduce((n,r)=>n+(r.input_rows||0),0),valid=runs.reduce((n,r)=>n+(r.valid_rows||0),0),invalid=runs.reduce((n,r)=>n+(r.invalid_rows||0),0),preview=runs.filter(r=>r.kind==='preview'),failed=preview.filter(r=>r.status==='Failed').length;
   const daily_runs=Array.from({length:7},(_,i)=>{const date=new Date();date.setUTCDate(date.getUTCDate()-(6-i));const key=date.toISOString().slice(0,10);return {date:key,runs:runs.filter(r=>String(r.created_at||'').slice(0,10)===key).length}});
   d={metrics:{runs_today:runs.filter(r=>String(r.created_at||'').slice(0,10)===today).length,successful_runs:runs.filter(r=>r.status==='Completed'&&String(r.created_at||'').slice(0,10)===today).length,failed_runs:runs.filter(r=>r.status==='Failed'&&String(r.created_at||'').slice(0,10)===today).length,validation_errors:runs.reduce((n,r)=>n+(r.issue_count??r.result?.issues?.length??0),0),rows_processed:rows,created:runs.reduce((n,r)=>n+(r.created_count||0),0),updated:runs.reduce((n,r)=>n+(r.updated_count||0),0),unchanged:runs.reduce((n,r)=>n+(r.unchanged_count||0),0),validation_success_rate:rows?Math.round(1000*valid/rows)/10:0,processing_failure_rate:preview.length?Math.round(1000*failed/preview.length)/10:0},daily_runs,recent_runs:runs.slice(0,10),tenant:{name:currentUser?.workspace||'Workspace'},plan:currentUser?.plan||'Basic'};
  }
  for(const run of (d.recent_runs||[]))if(run.result)cachedRunDetails.set(run.id,run);
  const m=d.metrics;
  $('#ops-health').innerHTML=[statCard('Total runs today',m.runs_today,'◷','UTC day'),statCard('Successful runs',m.successful_runs,'✓','Completed runs'),statCard('Failed runs',m.failed_runs,'!','Processing failures','kpi-danger'),statCard('Validation errors',m.validation_errors,'△','Rule issues','kpi-warn')].join('');
  $('#ops-outcomes').innerHTML=[statCard('Rows processed',m.rows_processed,'▤','All saved runs'),statCard('Created',m.created,'＋','Preview actions'),statCard('Updated',m.updated,'⇄','Preview actions'),statCard('Unchanged',m.unchanged,'＝','Preview actions'),statCard('Validation success',`${m.validation_success_rate}%`,'✓','Valid rows / rows checked'),statCard('Processing failure',`${m.processing_failure_rate}%`,'!','Failed previews / previews')].join('');
  const max=Math.max(1,...d.daily_runs.map(x=>x.runs));
  chart.innerHTML=d.daily_runs.map((x,i)=>`<div class="bar-group"><i class="bar ${i===d.daily_runs.length-1?'today':''}" style="height:${x.runs?Math.max(7,x.runs/max*83):2}%" title="${x.runs} runs"></i><span class="bar-label">${new Date(x.date+'T00:00:00Z').toLocaleDateString(undefined,{weekday:'short',timeZone:'UTC'})}</span></div>`).join('');
  table.innerHTML=runTable(d.recent_runs,d.tenant.name,d.plan);
 }catch(err){if(chart)chart.innerHTML=`<div class="empty-chart">${esc(err.message)} · Reload to retry</div>`;if(table)table.innerHTML=`<div class="form-error">${esc(err.message)}</div>`}
}

function runTable(runs,tenantName=currentUser?.workspace||'Workspace',plan=currentUser?.plan||'Basic'){
 if(!runs?.length)return `<div style="padding:35px;text-align:center;color:#7b8796;font-size:12px">No runs yet. Upload a batch or run the sample validation to begin.</div>`;
 return `<table class="data-table"><thead><tr><th>Run</th><th>Type / tenant</th><th>Rows</th><th>Created</th><th>Updated</th><th>Unchanged</th><th>Status</th><th>Time (UTC)</th><th>Actions</th></tr></thead><tbody>${runs.map(r=>`<tr><td><b>${esc(r.id.slice(0,10))}</b></td><td>${r.kind==='preview'?'Sync preview':'Validation'}<span class="table-tenant">${esc(tenantName)} · ${esc(plan)}</span></td><td>${r.input_rows}</td><td>${r.created_count}</td><td>${r.updated_count}</td><td>${r.unchanged_count}</td><td><span class="run-status ${r.status==='Failed'?'failed':r.kind==='validation'?'validation':''}">${esc(r.status)}</span></td><td>${new Date(r.created_at+'Z').toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})}</td><td><button class="run-action" data-run-id="${esc(r.id)}">View details</button>${plan==='Pro'&&r.kind==='preview'?` <button class="run-action" data-run-id="${esc(r.id)}" data-run-download="true">Export</button>`:''}</td></tr>`).join('')}</tbody></table>`;
}

async function loadRuns(target){try{const {runs}=await api('/api/runs');if(target==='all-runs')$('#all-runs').innerHTML=runTable(runs,currentUser?.workspace,currentUser?.plan);else if(target==='usage-data'){const d=await api('/api/usage');$('#usage-count').textContent=runs.length;$('#usage-rows').textContent=runs.reduce((a,r)=>a+r.input_rows,0);$('#usage-note').textContent=`${d.used} of ${d.limit} runs used today · ${d.remaining} remaining · UTC day ${d.date}`}}catch(e){let node=document.getElementById(target);if(node)node.innerHTML=`<div style="padding:25px;color:#778398;font-size:12px">${esc(e.message)}</div>`}}

document.addEventListener('click',async e=>{
 const page=e.target.closest('[data-page]');if(page){e.preventDefault();currentPage=page.dataset.page;renderDashboard();return}
 const view=e.target.closest('[data-run-id]');if(view){const id=view.dataset.runId;try{let d;try{d=await api('/api/runs/'+encodeURIComponent(id))}catch(err){if(err.status!==404||!cachedRunDetails.has(id))throw err;d=cachedRunDetails.get(id)}if(view.dataset.runDownload==='true')return downloadRun(d);openRunModal(d)}catch(err){toast(err.message)}}
});
function openRunModal(run){const issues=run.result?.issues||[],rows=run.result?.rows||[];const preview=run.kind==='preview';const detail=document.createElement('div');detail.className='run-modal-backdrop';detail.id='run-modal';detail.innerHTML=`<section class="run-modal" role="dialog" aria-modal="true"><header class="run-modal-head"><div><div class="eyebrow">${preview?'SYNC PREVIEW':'VALIDATION RUN'}</div><b>${esc(run.id)}</b></div><button class="run-modal-close" id="close-run">Close ✕</button></header><div class="run-modal-body"><div class="result-counts"><div class="count-pill"><b>${run.input_rows}</b> Input rows</div><div class="count-pill"><b>${run.valid_rows}</b> Valid</div><div class="count-pill"><b>${run.invalid_rows}</b> Invalid</div>${preview?`<div class="count-pill"><b>${run.created_count}</b> Create</div><div class="count-pill"><b>${run.updated_count}</b> Update</div><div class="count-pill"><b>${run.unchanged_count}</b> Unchanged</div>`:''}</div><p class="muted" style="font-size:11px">Status: <b>${esc(run.status)}</b> · ${new Date(run.created_at+'Z').toLocaleString()}</p>${preview?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Record</th><th>Action</th><th>Field changes</th><th>Reason</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.record_id)}</td><td><span class="tag ${x.action==='CREATE'?'tag-create':x.action==='UPDATE'?'tag-update':'tag-unchanged'}">${esc(x.action)}</span></td><td>${x.changes?.length?x.changes.map(c=>`${esc(c.field)}: ${esc(c.before)} → ${esc(c.after)}`).join('<br>'):'—'}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:11px">Preview only — no ERP write-back.</p>`:`<div class="table-wrap"><table class="data-table"><thead><tr><th>Row</th><th>Record</th><th>Rule</th><th>Field</th><th>Issue</th></tr></thead><tbody>${issues.length?issues.map(i=>`<tr class="issue"><td>${i.row}</td><td>${esc(i.record_id||'—')}</td><td>${esc(i.rule)}</td><td>${esc(i.field||'—')}</td><td>${esc(i.message)}</td></tr>`).join(''):`<tr><td colspan="5">No validation issues.</td></tr>`}</tbody></table></div>`}<div style="display:flex;justify-content:flex-end;margin-top:16px"><button class="btn btn-outline" id="export-run">Download ${preview?'preview':'validation'} JSON</button></div></div></section>`;document.body.append(detail);$('#close-run',detail).onclick=()=>detail.remove();detail.addEventListener('click',e=>{if(e.target===detail)detail.remove()});$('#export-run',detail).onclick=()=>downloadRun(run)}
function downloadRun(run){const blob=new Blob([JSON.stringify(run.result||run,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`syncshield-${run.id}.json`;a.click();URL.revokeObjectURL(url)}
function cacheSubmission(r,preview){if(!r.run_id)return;const result=preview?{...r}:{valid_rows:r.valid_rows,invalid_rows:r.invalid_rows,issues:r.issues||[],rows:r.rows||[]};cachedRunDetails.set(r.run_id,{id:r.run_id,kind:preview?'preview':'validation',status:r.status||'Completed',input_rows:r.input_rows||r.rows?.length||0,valid_rows:r.valid_rows??r.input_rows??0,invalid_rows:r.invalid_rows||0,issue_count:r.issues?.length||0,created_count:r.created||0,updated_count:r.updated||0,unchanged_count:r.unchanged||0,created_at:r.created_at||new Date().toISOString().replace('T',' ').slice(0,19),result})}
function showValidation(r){$('#results').innerHTML=`<div class="result-counts"><div class="count-pill"><b>${r.valid_rows}</b> Valid rows</div><div class="count-pill"><b>${r.invalid_rows}</b> Invalid rows</div><div class="count-pill">${r.issues.length?`${r.issues.length} issues found`:'No issues found'}</div>${r.run_id?`<div class="count-pill" style="margin-left:auto">Saved run <b style="font-size:12px">${esc(r.run_id)}</b></div>`:''}</div>${r.issues.length?`<div class="table-wrap card"><table class="data-table"><thead><tr><th>Row</th><th>Record</th><th>Rule</th><th>Field</th><th>Issue</th></tr></thead><tbody>${r.issues.map(i=>`<tr class="issue"><td>${i.row}</td><td>${esc(i.record_id||'—')}</td><td>${esc(i.rule)}</td><td>${esc(i.field||'—')}</td><td>${esc(i.message)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="card" style="padding:16px;color:#32805a;font-size:12px">✓ All rows passed validation. Your data is ready for review.</div>`}<div style="margin-top:10px;text-align:right"><button class="run-action" data-page="Run History">Open saved run history →</button></div>`}
function uploadPage(preview=false){const locked=preview&&currentUser?.plan!=='Pro';return `<div class="page-title"><div><div class="eyebrow">${preview?'PRO WORKSPACE TOOL':'DATA QUALITY'}</div><h1 style="margin-top:8px">${preview?'Sync Preview':'Data Quality Studio'}</h1><p>${preview?'Review proposed changes against the fixed demo baseline. Preview only — no ERP write-back.':'Upload, inspect and validate customer records before processing.'}</p></div>${preview?`<span class="badge-plan">${currentUser?.plan==='Pro'?'PRO ENABLED':'PRO PLAN'}</span>`:''}</div>${locked?`<section class="card" style="padding:25px;max-width:720px"><h3 style="font:700 16px Manrope">Sync Preview is a Pro feature</h3><p class="muted" style="font-size:12px">Your Basic workspace can validate customer batches and inspect validation results. Upgrade the workspace plan through an authorized administrator to enable preview runs.</p><button class="btn btn-dark" data-enable-pro>Enable Pro demo</button><p class="demo-plan-note">Prototype plan switch · no payment or ERP connection</p><button class="btn btn-outline" data-page="Usage & Plan">View plan & usage</button></section>`:`<section class="card"><div class="card-head"><h3>${preview?'Choose a batch to preview':'Upload customer batch'}</h3><span>CSV or JSON · up to 10 rows</span></div><div style="padding:18px"><div class="upload-zone"><div style="font-size:26px">↥</div><strong>Drop your customer file here</strong><p>CSV or JSON · Maximum 10 customer records</p><button type="button" class="btn btn-outline" id="browse-files">Browse files</button><input id="file-input" type="file" accept=".csv,.json,text/csv,application/json"><span id="selected-file" class="upload-file-name" aria-live="polite">No file selected</span><button class="btn btn-light" id="sample-btn" style="margin-left:7px">Use sample data</button></div><div id="batch-area"></div><div style="display:flex;justify-content:flex-end;gap:9px;margin-top:16px"><button class="btn btn-outline" id="clear-btn">Clear</button><button class="btn btn-dark" id="run-btn">${preview?'Generate preview':'Validate batch'} →</button></div><div id="results"></div></div></section>`}`}

function shell(content){return `<div class="app-shell"><aside class="sidebar" id="sidebar">${brand()}<div class="side-label">WORKSPACE</div>${navItems.map(([n,i])=>`<a href="#" class="side-link ${currentPage===n?'active':''}" data-page="${n}"><span class="ico">${i}</span>${n}${n==='Sync Preview'&&currentUser?.plan!=='Pro'?'<span style="margin-left:auto;font-size:9px">PRO</span>':''}</a>`).join('')}<div class="side-bottom"><div class="plan-box"><b>${esc(currentUser?.workspace||'Workspace')}</b>${esc(currentUser?.plan||'Basic')} plan<div style="margin-top:7px">Private workspace · Preview only</div></div><div class="profile-mini"><div class="avatar">${esc((currentUser?.name||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div style="flex:1"><b>${esc(currentUser?.name||'User')}</b><small>${esc(currentUser?.role||'Operator')}</small></div><button class="side-link" id="logout" title="Sign out">↪</button></div></div></aside><div class="main-area"><header class="app-top"><div><button class="mobile-menu" id="menu">☰</button><span class="crumb">${esc(currentUser?.workspace||'Workspace')} &nbsp; / &nbsp;${esc(currentPage)}</span></div><div class="top-user"><span class="badge-plan">${esc(currentUser?.plan||'Basic')} PLAN</span><div class="avatar">${esc((currentUser?.name||'U')[0].toUpperCase())}</div></div></header><main class="content">${content}</main></div></div>`}
function simplePage(){let page=currentPage;let text=page==='Usage & Plan'?'Workspace plan, daily quota and saved activity.':page==='Settings'?'Workspace settings and account preferences.':'Saved validation and preview history for this workspace.';return `<div class="page-title"><div><div class="eyebrow">${page==='Run History'?'AUDIT TRAIL':page==='Usage & Plan'?'WORKSPACE PLAN':'PREFERENCES'}</div><h1 style="margin-top:8px">${esc(page)}</h1><p>${esc(text)}</p></div></div>${page==='Usage & Plan'?`<section class="card" style="padding:24px;max-width:720px"><div class="eyebrow">CURRENT PLAN</div><h2 style="font:800 27px Manrope">${esc(currentUser?.plan||'Basic')}</h2><p class="muted" style="font-size:13px">${currentUser?.plan==='Pro'?'Sync preview enabled · 20 daily runs':'Batch validation · 3 daily runs'}</p><div class="grid-kpi" style="grid-template-columns:1fr 1fr;margin-top:20px"><div class="card kpi"><div class="kpi-top">Used today</div><div class="kpi-value" id="usage-count">—</div></div><div class="card kpi"><div class="kpi-top">Remaining today</div><div class="kpi-value" id="usage-remaining">—</div></div></div><div class="rate-track" style="height:8px"><i id="usage-meter" style="width:0"></i></div><p id="usage-note" class="muted" style="font-size:11px">Loading usage…</p><div style="border-top:1px solid var(--line);padding-top:15px;margin-top:14px;font-size:11px;color:#76847b">Daily limits use UTC. Usage is reserved only after request validation and accepted run creation. Retried idempotency keys do not debit twice.</div></section>`:page==='Settings'?`<section class="card" style="padding:24px;max-width:650px"><h3 style="font:700 16px Manrope">Workspace profile</h3><p class="muted" style="font-size:12px">${esc(currentUser?.workspace||'Workspace')} · ${esc(currentUser?.email||'')} · ${esc(currentUser?.role||'Operator')}</p><p class="muted" style="font-size:12px">Preferred format: ${esc(currentUser?.preferredFormat||'CSV')} · Subscription: ${esc(currentUser?.subscriptionStatus||'ACTIVE')}</p><button class="btn btn-outline" id="settings-logout">Sign out</button></section>`:`<section class="card"><div class="card-head"><div><h3>Workspace run history</h3><span>Private to ${esc(currentUser?.workspace||'this workspace')}</span></div><button class="btn btn-outline" data-page="Data Quality">＋ New validation</button></div><div id="all-runs" class="table-wrap" style="padding:10px">Loading runs…</div></section>`}`}
async function loadRuns(target){try{const {runs}=await api('/api/runs');for(const run of runs)if(run.result)cachedRunDetails.set(run.id,run);if(target==='all-runs')$('#all-runs').innerHTML=runTable(runs,currentUser?.workspace,currentUser?.plan);else if(target==='usage-data'){const d=await api('/api/usage');$('#usage-count').textContent=d.used;$('#usage-remaining').textContent=d.remaining;$('#usage-note').textContent=`${d.used} of ${d.limit} runs used today · resets at UTC midnight (${d.date})`;$('#usage-meter').style.width=`${Math.min(100,100*d.used/d.limit)}%`}}catch(e){let node=document.getElementById(target);if(node)node.innerHTML=`<div style="padding:25px;color:#778398;font-size:12px">${esc(e.message)}</div>`}}
function parseCustomerFile(text,name){let rows;if(name.toLowerCase().endsWith('.json'))rows=JSON.parse(text);else{const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<2)throw Error('CSV needs a header row and at least one record.');const parseLine=line=>{let out=[],cell='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&quoted&&line[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cell);cell=''}else cell+=c}out.push(cell);return out};const headers=parseLine(lines.shift()).map(x=>x.trim());rows=lines.map(line=>{const cells=parseLine(line);return Object.fromEntries(headers.map((h,i)=>[h,h==='version'?Number(cells[i]):cells[i]]))})}if(!Array.isArray(rows))throw Error('JSON file should contain an array of customer rows.');if(rows.length>10)throw Error('A batch may contain at most 10 rows.');return rows}
function wireBatch(){const area=$('#batch-area'),results=$('#results');if(!area)return;const zone=$('.upload-zone');const showRows=()=>{area.innerHTML=pendingRows.length?`<div class="card-head" style="padding:18px 0 10px;border:0"><h3>Batch preview · ${pendingRows.length} rows</h3><span>record_id · name · version · status</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Record ID</th><th>Name</th><th>Version</th><th>Status</th></tr></thead><tbody>${pendingRows.map(r=>`<tr><td>${esc(r.record_id)}</td><td>${esc(r.name)}</td><td>${esc(r.version)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`:''};const resetKey=()=>{pendingOperationKey=null;pendingOperationKind=null};const useFile=async f=>{try{if(!/\.(csv|json)$/i.test(f.name))throw Error('Choose a .csv or .json file.');if(f.size>1024*1024)throw Error('File is larger than the 1 MB upload limit.');pendingRows=parseCustomerFile(await f.text(),f.name);resetKey();$('#selected-file').textContent=`${f.name} · ${pendingRows.length} rows ready`;showRows();results.innerHTML=''}catch(ex){$('#selected-file').textContent=`Could not load ${f.name}`;results.innerHTML=`<div class="form-error">Could not read file: ${esc(ex.message)}</div>`}finally{$('#file-input').value=''}};showRows();$('#browse-files').onclick=()=>$('#file-input').click();$('#sample-btn').onclick=()=>{pendingRows=sample.map(x=>({...x}));resetKey();$('#selected-file').textContent='Sample data loaded';showRows();results.innerHTML=''};$('#clear-btn').onclick=()=>{pendingRows=[];resetKey();showRows();results.innerHTML='';$('#selected-file').textContent='No file selected'};$('#file-input').onchange=e=>{if(e.target.files[0])useFile(e.target.files[0])};zone.addEventListener('dragover',e=>{e.preventDefault();zone.style.borderColor='#6b9850'});zone.addEventListener('dragleave',()=>zone.style.borderColor='');zone.addEventListener('drop',e=>{e.preventDefault();zone.style.borderColor='';if(e.dataTransfer.files[0])useFile(e.dataTransfer.files[0])});$('#run-btn').onclick=async()=>{if(!pendingRows.length){results.innerHTML='<div class="form-error">Add rows or load the sample before continuing.</div>';return}const btn=$('#run-btn'),isPreview=currentPage==='Sync Preview',operationKind=isPreview?'preview':'validation';if(pendingOperationKind!==operationKind){pendingOperationKey=null;pendingOperationKind=operationKind}pendingOperationKey=pendingOperationKey||crypto.randomUUID();btn.disabled=true;btn.textContent='Working…';results.innerHTML='';try{const r=await api(isPreview?'/api/process':'/api/validate',{rows:pendingRows},{'Idempotency-Key':pendingOperationKey});resetKey();cacheSubmission(r,isPreview);if(isPreview)showPreview(r);else showValidation(r);toast(isPreview?'Sync preview saved to run history':'Validation complete · run saved to history')}catch(ex){if(isPreview&&ex.data?.error_code==='VALIDATION_BLOCKED')showPreviewBlocked(ex.data);else results.innerHTML=`<div class="form-error">${esc(ex.message)}${ex.data?.issues?'<ul>'+ex.data.issues.map(i=>`<li>${esc(i.rule)} · Row ${i.row}: ${esc(i.message)}</li>`).join('')+'</ul>':''}</div>`}finally{btn.disabled=false;btn.textContent=currentPage==='Sync Preview'?'Validate & generate preview →':'Validate batch →'}}}

// Data Quality Studio: row-level validation results and downloadable audit report.
let qualityReport=null;
function showValidation(r){
 qualityReport=r;const rules=[...new Set((r.issues||[]).map(i=>i.rule))].sort();
 $('#results').innerHTML=`<div class="quality-summary"><div><span>Rows checked</span><b>${r.rows?.length??r.valid_rows+r.invalid_rows}</b></div><div><span>Valid rows</span><b class="quality-good">${r.valid_rows}</b></div><div><span>Invalid rows</span><b class="quality-bad">${r.invalid_rows}</b></div><div><span>Rule violations</span><b>${r.issues?.length||0}</b></div>${r.run_id?`<div class="quality-run">Saved to run history · ${esc(r.run_id)}</div>`:''}</div>
 <div class="quality-toolbar"><div><b>Row-level results</b><p>Each invalid row shows its error code, rule, column and explanation.</p></div><div class="quality-filters"><label>Status <select id="quality-status"><option value="all">All rows</option><option value="invalid">Invalid only</option><option value="valid">Valid only</option></select></label><label>Rule ID <select id="quality-rule"><option value="all">All rules</option>${rules.map(rule=>`<option value="${esc(rule)}">${esc(rule)}</option>`).join('')}</select></label><button class="btn btn-outline" id="quality-download">Download report</button></div></div><div id="quality-table"></div>
 <div class="quality-block-note"><b>When processing is blocked</b><span>Sync Preview requires every row to pass validation. Invalid batches are blocked before a preview run is created; this table identifies what to fix.</span></div><div style="margin-top:10px;text-align:right"><button class="run-action" data-page="Run History">Open saved run history →</button></div>`;
 const render=()=>renderQualityRows($('#quality-table'),r,$('#quality-status').value,$('#quality-rule').value);$('#quality-status').onchange=render;$('#quality-rule').onchange=render;$('#quality-download').onclick=()=>downloadValidationReport(r);render();
}
function renderQualityRows(target,r,status,rule){
 const byRow=new Map();for(const i of r.issues||[]){const a=byRow.get(i.row)||[];a.push(i);byRow.set(i.row,a)}let rows=(r.rows||[]).map((row,index)=>({row,index:index+1,issues:byRow.get(index+1)||[]}));
 if(status==='invalid')rows=rows.filter(x=>x.issues.length);if(status==='valid')rows=rows.filter(x=>!x.issues.length);if(rule!=='all')rows=rows.filter(x=>x.issues.some(i=>i.rule===rule));
 target.innerHTML=rows.length?`<div class="table-wrap"><table class="data-table quality-table"><thead><tr><th>Row</th><th>Result</th><th>Record ID</th><th>Error code</th><th>Rule ID</th><th>Column</th><th>Explanation</th></tr></thead><tbody>${rows.map(x=>{const bad=x.issues.length>0;const details=bad?x.issues.filter(i=>rule==='all'||i.rule===rule):[null];return details.map(i=>`<tr class="${bad?'issue':''}"><td>${x.index}</td><td><span class="quality-pill ${bad?'invalid':'valid'}">${bad?'Invalid':'Valid'}</span></td><td>${esc(x.row?.record_id||'—')}</td><td>${i?esc(i.code||`VAL_${i.rule}`):'—'}</td><td>${i?esc(i.rule):'—'}</td><td>${i?esc(i.field||'—'):'—'}</td><td>${i?esc(i.message):'Passed all validation rules.'}</td></tr>`).join('')}).join('')}</tbody></table></div>`:`<div class="quality-empty">No rows match these filters.</div>`;
}
function downloadValidationReport(r){
 const byRow=new Map();for(const i of r.issues||[]){const a=byRow.get(i.row)||[];a.push(i);byRow.set(i.row,a)}const out=[['row','status','record_id','error_code','rule_id','column','explanation']];
 (r.rows||[]).forEach((row,index)=>{const list=byRow.get(index+1)||[];if(!list.length)out.push([index+1,'Valid',row?.record_id||'','','','','Passed all validation rules.']);else list.forEach(i=>out.push([index+1,'Invalid',i.record_id||row?.record_id||'',i.code||`VAL_${i.rule}`,i.rule,i.field||'',i.message]))});
 const csv=out.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`syncshield-validation-${r.run_id||'report'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

// Pro Synchronisation Preview workbench.
function uploadPage(preview=false){
 const locked=preview&&currentUser?.plan!=='Pro';
 const title=preview?'Synchronisation Preview':'Data Quality Studio';
 const intro=preview?'Compare a valid incoming batch with the fixed baseline and review exact proposed changes.':'Validate customer batches against the four data rules and review row-level errors.';
 const rules=preview?`<details class="preview-rule-gate"><summary><span><b>Validation gate</b><small>Four rules · any invalid row blocks preview generation</small></span><span class="preview-gate-count">R1–R4</span></summary><div class="preview-rule-grid"><div><b>R1 · Record ID</b><span>Required, non-empty string, maximum 20 characters, unique within this batch.</span><small>Example: duplicate C01.</small></div><div><b>R2 · Name</b><span>After trimming, must contain 1–40 characters.</span><small>Example: blank name.</small></div><div><b>R3 · Version</b><span>Integer from 1 through 100.</span><small>Examples: 0, 101, or "2".</small></div><div><b>R4 · Status</b><span>Must be ACTIVE or INACTIVE.</span><small>Example: UNKNOWN.</small></div></div></details>`:'';
 return `<div class="page-title preview-page-title"><div><div class="eyebrow">${preview?'PRO WORKSPACE TOOL':'DATA QUALITY'}</div><h1 style="margin-top:8px">${title}</h1><p>${intro}</p></div>${preview?`<span class="badge-plan">${locked?'PRO PLAN':'PRO ENABLED'}</span>`:''}</div>${locked?`<section class="card preview-locked"><div class="preview-locked-icon">⇄</div><h2>Preview every proposed change</h2><p>Sync Preview is included with Pro. Your Basic workspace can validate batches and inspect validation history.</p><button class="btn btn-dark" data-enable-pro>Enable Pro demo</button><p class="demo-plan-note">Prototype plan switch · no payment or ERP connection</p><button class="btn btn-outline" data-page="Usage & Plan">View plan & usage</button></section>`:`${preview?`<div class="preview-safety"><span class="preview-safety-icon">◈</span><div><b>Preview only — no ERP write-back</b><span>Incoming rows are compared to the seeded baseline. No live ERP is contacted or modified.</span></div><span class="preview-mode-tag">SAFE MODE</span></div><section class="preview-baseline-panel"><div class="preview-baseline-top"><div><span>STEP 1 · EXISTING ERP SNAPSHOT</span><h2>Load old customer data as the baseline</h2><p>Upload the old CSV/JSON first. SyncShield saves it only inside this signed-in workspace.</p></div><div class="baseline-controls"><button type="button" class="btn btn-outline" id="baseline-browse">Choose old data</button><input id="baseline-file-input" type="file" accept=".csv,.json,text/csv,application/json"><button type="button" class="btn btn-light" id="baseline-seeded">Restore seeded baseline</button></div></div><span id="baseline-file-status" class="baseline-file-status">Loading workspace baseline…</span><div id="baseline-records" class="baseline-record-list"></div><small class="baseline-expected">Then upload new incoming data below. Matching IDs become UPDATE or UNCHANGED; IDs not found in this baseline become CREATE.</small></section>${rules}`:''}<section class="card preview-upload-card"><div class="card-head"><div><div class="eyebrow">${preview?'STEP 2 · NEW INCOMING DATA':'DATA QUALITY · VALIDATION'}</div><h3>${preview?'Upload new records for comparison':'Upload a batch for validation'}</h3><p>${preview?'This is the new dataset. It will be compared row by row with the old data loaded above.':'Check required fields, value formats and duplicate record IDs.'}</p></div><span>CSV or JSON · up to 10 rows</span></div><div style="padding:18px"><div class="upload-zone"><div style="font-size:26px">${preview?'⇄':'↥'}</div><strong>${preview?'Choose the new customer dataset':'Drop your customer file here'}</strong><p>${preview?'We validate the batch, then show only proposed changes.':'CSV or JSON · Maximum 10 customer records'}</p><button type="button" class="btn btn-outline" id="browse-files">${preview?'Choose new data':'Browse files'}</button><input id="file-input" type="file" accept=".csv,.json,text/csv,application/json"><span id="selected-file" class="upload-file-name" aria-live="polite">No file selected</span><button class="btn btn-light" id="sample-btn" style="margin-left:7px">${preview?'Load preview sample':'Use sample data'}</button></div><div id="batch-area"></div><div style="display:flex;justify-content:flex-end;gap:9px;margin-top:16px"><button class="btn btn-outline" id="clear-btn">Clear</button><button class="btn btn-dark" id="run-btn">${preview?'Validate & generate preview':'Validate batch'} →</button></div><div id="results"></div></div></section>`}`;
}
function showPreviewBlocked(data){
 const issues=data.issues||[],invalidRows=new Set(issues.map(i=>i.row)),rules={R1:'Record ID must be non-empty, at most 20 characters, and unique within the batch.',R2:'Name must contain 1–40 characters after trimming.',R3:'Version must be an integer from 1 through 100.',R4:'Status must be ACTIVE or INACTIVE.'};
 $('#results').innerHTML=`<section class="preview-blocked"><div class="preview-blocked-head"><span class="preview-blocked-icon">!</span><div><div class="eyebrow">PREVIEW BLOCKED · VALIDATION FAILED</div><h2>No sync preview was generated</h2><p>${esc(data.reason||'Fix all listed errors, then generate the preview again.')}</p></div></div><div class="preview-blocked-counts"><div><b>${pendingRows.length}</b><span>Incoming rows</span></div><div class="bad"><b>${invalidRows.size}</b><span>Invalid rows</span></div><div><b>${issues.length}</b><span>Rule violations</span></div></div><div class="preview-error-list"><h3>Errors to fix</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>ROW</th><th>RECORD ID</th><th>ERROR CODE</th><th>RULE</th><th>COLUMN</th><th>WHAT TO FIX</th></tr></thead><tbody>${issues.map(i=>`<tr class="issue"><td>${i.row}</td><td>${esc(i.record_id||pendingRows[i.row-1]?.record_id||'—')}</td><td>${esc(i.code||`VAL_${i.rule}`)}</td><td><b>${esc(i.rule)}</b></td><td>${esc(i.field||'—')}</td><td>${esc(i.message||rules[i.rule]||'Correct this field and retry.')}</td></tr>`).join('')}</tbody></table></div></div><div class="preview-rule-explainer"><b>Why blocked?</b><span>Every input row must pass R1–R4. Invalid rows are counted once even when they have multiple violations. This request created no preview run, used no quota, and made no ERP changes.</span></div><button type="button" class="btn btn-outline" id="retry-validation">Review incoming rows</button></section>`;
 $('#retry-validation').onclick=()=>$('#batch-area')?.scrollIntoView({behavior:'smooth',block:'center'});
}
function drawBaseline(){
 const target=$('#baseline-records');if(!target)return;
 target.innerHTML=activeBaselineRows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>EXISTING ID</th><th>CUSTOMER</th><th>VERSION</th><th>STATUS</th></tr></thead><tbody>${activeBaselineRows.map(r=>`<tr><td><b>${esc(r.record_id)}</b></td><td>${esc(r.name)}</td><td>${esc(r.version)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="quality-empty">No baseline records loaded.</div>';
}
async function wireBaseline(){
 const status=$('#baseline-file-status'),picker=$('#baseline-file-input');
 try{const data=await api('/api/baseline');activeBaselineRows=data.rows||[];status.textContent=`${data.source==='seeded'?'Seeded':'Workspace'} baseline · ${activeBaselineRows.length} records` ;drawBaseline()}catch(err){status.textContent=err.message}
 const saveRows=async(rows,label)=>{status.textContent='Checking baseline rules…';try{const result=await api('/api/baseline',{rows});activeBaselineRows=result.rows;status.textContent=result.message;drawBaseline();toast(result.message)}catch(err){status.textContent=err.message;if(err.data?.issues){const list=err.data.issues.map(i=>`Row ${i.row} · ${i.code||i.rule} · ${i.field}: ${i.message}`).join(' | ');status.textContent=`${err.message} ${list}`} }};
 $('#baseline-browse').onclick=()=>picker.click();
 picker.onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!/\.(csv|json)$/i.test(file.name))throw Error('Choose a .csv or .json old-baseline file.');if(file.size>1024*1024)throw Error('File is larger than the 1 MB upload limit.');status.textContent=`Reading ${file.name}…`;const rows=parseCustomerFile(await file.text(),file.name);await saveRows(rows, file.name)}catch(err){status.textContent=`Could not load baseline: ${err.message}`}finally{picker.value=''}};
 $('#baseline-seeded').onclick=()=>saveRows([{record_id:'C01',name:'Anu',version:1,status:'ACTIVE'}],'seeded baseline');
}
function showPreview(result){
 const items=result.rows||[],created=result.created??items.filter(x=>x.action==='CREATE').length,updated=result.updated??items.filter(x=>x.action==='UPDATE').length,unchanged=result.unchanged??items.filter(x=>x.action==='UNCHANGED').length;
 const host=$('#results');if(!host)return;
 const runMeta=result.run_id?`<span class="preview-run-id">Saved run · ${esc(result.run_id)}</span>`:'';
 host.innerHTML=`<section class="preview-results"><div class="preview-results-head"><div><div class="eyebrow">STEP 2 · REVIEW PROPOSED CHANGES</div><h2>Here’s what would happen</h2><p>Review each record before you decide what to do next.</p></div><div class="preview-export"><button class="btn btn-outline" id="preview-export-csv">Export CSV ↓</button><button class="btn btn-dark" id="preview-export-json">Export JSON ↓</button></div></div><div class="preview-safety compact"><span class="preview-safety-icon">◈</span><div><b>Preview only — no ERP write-back</b><span>This is a proposed change set. No data has been sent to an ERP.</span></div>${runMeta}</div><div class="preview-counts"><div class="preview-count create"><span>CREATE</span><b>${created}</b><small>New records</small></div><div class="preview-count update"><span>UPDATE</span><b>${updated}</b><small>Changed records</small></div><div class="preview-count unchanged"><span>UNCHANGED</span><b>${unchanged}</b><small>No differences</small></div><div class="preview-total"><span>TOTAL RECORDS</span><b>${items.length}</b></div></div><div class="preview-table-head"><div><h3>Proposed changes</h3><p>Compare existing baseline values with incoming batch values.</p></div><div class="preview-filters"><label class="preview-search"><span>⌕</span><input id="preview-search" type="search" placeholder="Search record ID or name…" aria-label="Search proposed changes"></label><select id="preview-action-filter" aria-label="Filter by action"><option value="all">All actions</option><option value="CREATE">CREATE</option><option value="UPDATE">UPDATE</option><option value="UNCHANGED">UNCHANGED</option></select></div></div><div id="preview-table"></div><div class="preview-footer-note"><span>✓</span>Review complete? Export this proposed change set for your records. Nothing is written back to your ERP.</div></section>`;
 const draw=()=>renderPreviewTable($('#preview-table'),items,$('#preview-search').value,$('#preview-action-filter').value);
 $('#preview-search').addEventListener('input',draw);$('#preview-action-filter').addEventListener('change',draw);draw();
 $('#preview-export-csv').onclick=()=>downloadPreviewCsv(result);$('#preview-export-json').onclick=()=>downloadRun({id:result.run_id||'preview',result:{...result,preview_only:true,erp_write_back:false}});
}
function renderPreviewTable(target,items,query,action){
 const q=(query||'').trim().toLowerCase();const rows=items.filter(x=>(action==='all'||x.action===action)&&(!q||String(x.record_id||'').toLowerCase().includes(q)||String(x.incoming?.name||'').toLowerCase().includes(q)));
 target.innerHTML=rows.length?`<div class="table-wrap preview-table-wrap"><table class="data-table preview-table"><thead><tr><th>RECORD</th><th>ACTION</th><th>EXISTING VALUE</th><th>INCOMING VALUE</th><th>WHY THIS ACTION</th></tr></thead><tbody>${rows.map(x=>{const before=x.baseline||null,after=x.incoming||{};const fields=['name','version','status'];const value=(obj,key)=>obj?esc(obj[key]??'—'):'<span class="preview-empty-value">No existing record</span>';return `<tr><td><div class="preview-record"><span class="preview-record-icon">${esc(String(x.record_id||'?').slice(0,1))}</span><div><b>${esc(x.record_id||'—')}</b><small>${esc(after.name||'Customer record')}</small></div></div></td><td><span class="preview-action ${String(x.action||'').toLowerCase()}"><i></i>${esc(x.action)}</span></td><td><div class="preview-values">${fields.map(k=>`<div><span>${k}</span><b>${value(before,k)}</b></div>`).join('')}</div></td><td><div class="preview-values incoming">${fields.map(k=>`<div><span>${k}</span><b>${value(after,k)}</b></div>`).join('')}</div></td><td><span class="preview-reason">${esc(x.reason||'No change reason supplied.')}</span>${x.changes?.length?`<small class="preview-changes">${x.changes.length} field${x.changes.length===1?'':'s'} differ from baseline</small>`:''}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="quality-empty">No proposed changes match your search and action filters.</div>`;
}
function downloadPreviewCsv(result){
 const fields=['name','version','status'];const out=[['record_id','action','field','existing_value','incoming_value','reason']];
 (result.rows||[]).forEach(x=>fields.forEach(field=>out.push([x.record_id,x.action,field,x.baseline?.[field]??'',x.incoming?.[field]??'',x.reason||''])));
 const csv=out.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`syncshield-preview-${result.run_id||'export'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-enable-pro]');if(!button)return;
 button.disabled=true;button.textContent='Enabling Pro…';
 try{const data=await api('/api/plan',{plan:'Pro'});currentUser=data.user;await renderDashboard();toast('Pro demo enabled for this workspace');}
 catch(err){button.disabled=false;button.textContent='Enable Pro demo';toast(err.message)}
});

function checkoutPage(){
 const months=Number(checkoutMonths)||1,total=999*months;
 const countries=['India','United States','United Kingdom','Canada','Australia','Singapore','United Arab Emirates','Germany','France','Japan','Other'];
 return `<div class="checkout-wrap"><button class="checkout-back" id="checkout-back">← Back to administration</button><div class="checkout-grid"><section class="card checkout-card"><div class="eyebrow">SECURE PAYMENT</div><h1>Complete your Pro payment</h1><p class="checkout-lead">Review your advance period and continue to the payment provider’s secure checkout.</p><div class="checkout-price"><div><span>SyncShield Pro</span><b>${months} month${months===1?'':'s'} advance period</b></div><strong>₹${total.toLocaleString('en-IN')}</strong></div><div class="checkout-line"><span>Plan price</span><b>₹999 × ${months}</b></div><div class="checkout-line total"><span>Total due today</span><b>₹${total.toLocaleString('en-IN')} INR</b></div><div class="checkout-security"><span class="checkout-lock">⌑</span><div><b>Payment details stay with the payment provider</b><span>Card number, expiry, CVV, UPI PIN, and online banking credentials are entered only on the provider’s hosted payment page. SyncShield never receives or stores them.</span></div></div><div class="checkout-methods"><h2>Available payment methods</h2><div class="checkout-method-grid"><div><b>▰ &nbsp; Credit & debit cards</b><span>Enter cardholder name and card details securely at checkout.</span></div><div><b>◉ &nbsp; UPI · Google Pay</b><span>Shown when supported for your account and payment.</span></div><div><b>▤ &nbsp; Net banking</b><span>Choose an eligible bank from the provider’s current list.</span></div><div><b>⇄ &nbsp; Bank transfer</b><span>Available when enabled by the provider for this payment.</span></div></div></div><div id="checkout-error"></div><button class="btn btn-dark checkout-submit" id="checkout-submit">Continue to secure payment · ₹${total.toLocaleString('en-IN')} →</button><p class="checkout-footnote">You’ll be redirected to the payment provider. Bank availability, wallets and Google Pay vary by country, currency and provider account.</p></section><aside class="card checkout-billing"><span class="checkout-step">BILLING DETAILS</span><h2>Account information</h2><p>Used to prefill the secure checkout.</p><label>Name<input value="${esc(currentUser?.name||'')}" readonly autocomplete="name"></label><label>Email<input value="${esc(currentUser?.email||'')}" readonly autocomplete="email"></label><label for="billing-country">Billing country</label><select id="billing-country">${countries.map(c=>`<option ${c==='India'?'selected':''}>${c}</option>`).join('')}</select><div class="checkout-merchant"><span>MERCHANT</span><b>SyncShield</b><small>Advance workspace subscription</small></div></aside></div></div>`;
}
function wireCheckout(){
 $('#checkout-back')?.addEventListener('click',()=>{currentPage='Administration';renderDashboard()});
 $('#checkout-submit')?.addEventListener('click',async()=>{const button=$('#checkout-submit'),error=$('#checkout-error');button.disabled=true;button.textContent='Connecting securely…';error.innerHTML='';try{const d=await api('/api/payments/checkout',{months:Number(checkoutMonths)});location.assign(d.checkout_url)}catch(err){error.innerHTML=`<div class="checkout-config-error"><b>Checkout unavailable</b><span>${esc(err.message)}</span></div>`;button.disabled=false;button.textContent=`Continue to secure payment · ₹${(999*(Number(checkoutMonths)||1)).toLocaleString('en-IN')} →`}});
}
